"""learn.py — 把教师产物/新说法写进快路径表(additive=True: 只在规则 unknown 时接管)

  python -m opencode_fastpath.learn --intent launch_app --arg 记事本 --text "开一下记事板" --text "打开记事板"
  python -m opencode_fastpath.learn --intent dsh_run --arg "" --text "跑一下回归" --additive 1
"""
from __future__ import annotations

import argparse
import time

from .fastpath import FastPath


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--intent", required=True)
    ap.add_argument("--arg", default=None)
    ap.add_argument("--text", action="append", required=True, help="触发说法(可多次)")
    ap.add_argument("--additive", type=int, default=1, help="1=只在规则 unknown 时接管(默认); 0=仅影子对照")
    ap.add_argument("--note", default="")
    ap.add_argument("--table", default=None)
    args = ap.parse_args()

    fp = FastPath(table_path=args.table, mode="off")
    rep = fp.install(args.intent, args.arg, args.text, additive=bool(args.additive),
                     markers={"source": "learn", "note": args.note, "ts": time.time()})
    print(f"[OPENCODE] 已入库: entry#{rep['id']}  intent={rep['intent']}  arg={rep['arg']}"
          f"  destructive={rep['destructive']}")
    for t in rep["triggers"]:
        r = fp.route(t)
        print(f"   「{t}」  key={r['key']}  → {r['decision']} {r['intent'] or ''} {r['arg'] or ''}"
              f"  (additive={r['additive']}, blocked={r['blocked']})")
    st = fp.stats()
    print(f"   表: 条目 {st['entries']}  全串行 {st['full']}  前缀行 {st['prefix']}  表体 {st['bytes']}B")


if __name__ == "__main__":
    main()
